  assert.equal(sentenceCount("She said 'hello.' He waved."), 2);
});

test('recognizes terminator followed by closing bracket then whitespace', () => {
  assert.equal(sentenceCount('See the note (here). It was helpful.'), 2);
});

test('recognizes terminator followed by closing parenthesis then whitespace', () => {
  assert.equal(sentenceCount('Example (test). More text.'), 2);
});

test('recognizes multiple closing quotes/brackets after terminator', () => {
